fit_data_path = 'e:\SHARE\Fe\Data\analysis\06_fit_with_J0';
if ~exist('fit_resEi800','var')
    fit_data_file = 'FitEn_cut800br200_2D_fit_bgSer.mat';%Externaly 2-exponent fit fixed bg at high momentum.
    ld = load(fullfile(fit_data_path,fit_data_file));
    fit_resEi800 = ld.fit_res;
end
data_path = 'e:\SHARE\Fe\Data\analysis\06_fit_with_J0\sym4D_cutsAndFits';
fit_file = 'multicuts_fit_dataGH_ei800meV.mat';
if ~exist('cuts2fit800','var')
    ld = load(fullfile(data_path,fit_file));
    cuts2fit800 = ld.cuts2fit800;
end
cuts2fit = cuts2fit800;
fit_res = fit_resEi800;
mi = maps_instrument(787,600,'S');
sample=IX_sample(true,[1,0,0],[0,1,0],'cuboid',[0.04,0.03,0.02]);
cl = {cuts2fit800.cut2fit010_dir100} %[output:05312dbd]
for i=1:numel(cl)
    cl{i} = cl{i}.set_instrument(mi);
    cl{i} = cl{i}.set_sample(sample);

    %cuts2fit.cutsS_list{i} = cuts2fit.cutsS_list{i}.set_instrument(mi);
    %cuts2fit.cutsS_list{i} = cuts2fit.cutsS_list{i}.set_sample(sample);
end
cuts2fit800.cut2fit010_dir100 = cl{1};
%%
acolor b
Sgnl = fit_res.S;
pd(Sgnl);ly 0 1.5;liny;keep_figure %[output:12fbcd2d]
J0 = fit_res.J0;
pd(J0);ly 20 60;keep_figure %[output:295c256e]
% incorrect units fixture
G = fit_res.gamma;
G.s_axis.units = 'meV';
fit_res.gamma = G;
pd(G);ly 0 200;keep_figure %[output:804bac41]

dE = min(Sgnl.x(2:end)-Sgnl.x(1:end-1)) %[output:3bce4435]
e_min = Sgnl.x(1);

%%
En = 160 %[output:6b5fd6fa]
dE_step = 4; %original energy transfer step data were binned to. No point in going finer
half_dE = 10;
en_idx =  floor((En-e_min)/dE)+1;
%the2Dcuts = cuts2fit.cutsS_list;%(1:2);
the2Dcuts =cl;

%init_bg_params =
%cellfun(@(par)[par(1),par(3)],init_bg_params,'UniformOutput',false); % bg
%in case of 2-D fitting
%[fit_obj,fit_par,figa,figb]=fit_single_set(the2Dcuts,En,half_dE,dE_step,init_fg_params,init_bg_params,false)
%the2Dcuts{3} = cut(the2Dcuts{3},[-1,0.02,1],[]);
lfit_par = fit_res.all_fit_par(en_idx);
[fit_obj,fit_par,figa,figb]=refit_singleset_picks(the2Dcuts,En,half_dE,dE_step,lfit_par,0.2,true); %[output:229e9bc3] %[output:0e307a13] %[output:28cf50f6] %[output:303ffb7f] %[output:9d7aedf5] %[output:1550fad7] %[output:014d7275]
%%
%fit_res.all_fit_par(en_idx) = fit_par;
fit_res.all_fit_par(en_idx).p = fit_par.p;
acolor r
plot(fit_res.S);ly 0 1.5;liny;
acolor b
Sgnl.signal(en_idx) = fit_par.p(4);
pd(Sgnl);ly 0 1.5;liny;keep_figure

acolor r
plot(fit_res.J0);ly 10 50;liny;
acolor b
J0.signal(en_idx) = fit_par.p(6);
pd(J0);ly 10 50;keep_figure

acolor r
plot(fit_res.gamma);ly 0 200;liny;
acolor b
G.signal(en_idx) = fit_par.p(3);
pd(G);ly 0 200;keep_figure
%%
n_runs = numel(fit_res.all_fit_par);
all_fit_par = cell(1,n_runs);
Sg = fit_res.S;
s_sig = Sg.signal;
J0 = fit_res.J0;
j_sig = J0.signal;
G = fit_res.gamma;
g_sig = G.signal;
for idx = 1:n_runs
    cur_fit = fit_res.all_fit_par(idx);
    En = cur_fit.en;
    en_range = cur_fit.en_range;
    half_dE = 0.5*(en_range(3)-en_range(1));
    dE_step = en_range(2);
    %             refit_singleset_picks(the2Dcuts,En,half_dE,dE_step,lfit_par,0.2,true)
    [~,ftpr,figa]=refit_singleset_picks(the2Dcuts,En,half_dE,dE_step,cur_fit,0.2,true);
    all_fit_par{idx} = ftpr;
    s_sig(idx) = ftpr.p(4);
    j_sig(idx) = ftpr.p(6);
    g_sig(idx) = ftpr.p(3);
end
Sg.signal = s_sig;
J0.signal = j_sig;
G.signal  = g_sig;
%%

num_bp = cellfun(@(x)(numel(x.bp)),all_fit_par);
mbp = max(num_bp);
bp_plot = nan(mbp,numel(num_bp));
bp_sig  = nan(mbp,numel(num_bp));
en_axis = Sg.x;
for i=1:numel(all_fit_par)
    bpl = all_fit_par{i}.bp;
    bgs = all_fit_par{i}.bsig;
    for j=1:numel(bpl)
        if iscell(bpl)
            bp_plot(j,i)= bpl{j}(1);
            bp_sig(j,i) = bgs{j}(1);            
        else
            bp_plot(j,i) = bpl(1);
            bp_sig(j,i) = bgs(1);            
        end
    end
end
bg_data = repmat(IX_dataset_1d(),1,4);
for j=1:4
    bg_data(j) = IX_dataset_1d(en_axis,bp_plot(j,:),bp_sig(j,:));
end
pd(bg_data); keep_figure;
%%
acolor r
plot(fit_res.S);ly 0 1.5;liny;
acolor b
pd(Sg);ly 0 1.5;liny;keep_figure

acolor r
plot(fit_res.J0);ly 10 50;liny;
acolor b
pd(J0);ly 10 50;keep_figure

acolor r
plot(fit_res.gamma);liny;
acolor b
pd(G);ly 0 250;keep_figure
%%

%%
Sgnl.s_axis.units = 'meV';
fit_res.S = Sgnl;
fit_res.J0 = J0;
fit_res.gamma = G;
%save(fullfile(fit_data_path,fit_data_file),"fit_res");

